/*updateMasterMpRqBuyerReNote*/
UPDATE	ICOMCMPY
SET		RE_NOTE = #{st_remark1}
WHERE	1=1
AND		COM_CODE = #{st_buyer_code}
AND		STATUS IN ('C', 'R')


/*updateMasterMpRqBuyerRemarkOne*/
UPDATE	ICOMCOD2
SET		TEXT1 = #{REMARK},
		ADD_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
WHERE	1=1
AND		TYPE = #{TYPE}
AND		COMPANY_CODE = 'KRKORE0001'
AND		CODE = #{st_buyer_code}
AND		FLAG = 'Y'
